using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using Mimiclay.Sim;

namespace Mimiclay;

/// <summary>
/// The networked-sim COLLISION LAB (2026-11-07). Runs in Assets/scenes/Tests/SimLab.scene (generated by
/// Tools/SimLab/make_scene.pl): one STATION per scenario — an empty GameObject "SimLab.&lt;scenario&gt;" whose children are
/// markers (A, A.to, B, L, H, Hobs, ...) and the station's static geometry; clay footballs at the L markers become loose
/// props. Three debug clients take the roles A and B (player props) and H (hunter); the editor is the host.
/// Driven from Tools/SimLab/lab.sh through sbox-cli run_csharp — see Tools/SimLab/README.md:
/// <list type="bullet">
/// <item><see cref="Setup"/> (host) puts the cast and the station's loose prop on their markers.</item>
/// <item><see cref="HunterPrepare"/> (H) grabs what the scenario holds, or stands at the watch spot.</item>
/// <item><see cref="Run"/> (every screen, at once) acts the role's part and records the DRAWN poses each frame: velocity
/// jumps (blips), fading offsets, drawing-source switches, the scenario pair's closest centre distance, drawn box overlap
/// depth and vertical gap (landings), and for throws a tick-stamped HIT TIMELINE (release, copy hit, drawn reaction,
/// drawn arrival). Compare each screen with the host's line (the truth).</item>
/// </list>
/// </summary>
public static class SimLab
{
	public static readonly string[] Scenarios = { "loose", "static", "push", "headon", "held", "swing", "throw", "jump", "lying", "wall", "ledge", "pushwall", "twopush", "throwplayer", "climb", "corner", "inner", "hcorner" };

	// Climbing (2026-11-07): A climbs a wall and mantles onto it, climbs round a pillar (outer corners), along into an inner
	// corner; H (a hunter) climbs round a pillar. Longer runs, and the report adds the faces climbed (ClimbReport).
	static bool ClimbScen( string scen ) => scen is "climb" or "corner" or "inner" or "hcorner";

	// ── Scene access ────────────────────────────────────────────────────────────────────────────────────────

	static Scene S => Game.ActiveScene;
	static SimWorld Sim => S?.GetSystem<SimWorld>();

	static GameObject Station( string scen ) => S.GetAllObjects( true ).FirstOrDefault( g => g.Name == "SimLab." + scen );

	static Vector3? Marker( string scen, string name )
	{
		var c = Station( scen )?.Children.FirstOrDefault( x => x.Name == name );
		return c?.WorldPosition;
	}

	static GameObject StaticOf( string scen, string name )
		=> Station( scen )?.Children.FirstOrDefault( x => x.Name == name && x.Components.Get<Collider>() is not null ) // (the box, not the marker of the same name)
			?? S.GetAllObjects( true ).FirstOrDefault( g => g.Name == $"SimLab.{scen}.{name}" );

	// A player by CONNECTION ID (what lab.sh cast records), or by display name as a fallback. Names aren't unique: two
	// test clients once both came up as "Ned", and every lookup found the same body for A and B.
	static HiderController PropOf( string player )
		=> S.GetAllComponents<HiderController>().FirstOrDefault( h => !PropClaims.IsReleased( h ) && h.Network.Owner is { } o && o.Id.ToString() == player )
			?? S.GetAllComponents<HiderController>().FirstOrDefault( h => !PropClaims.IsReleased( h ) && h.Network.Owner?.DisplayName == player );

	/// <summary>The station's loose prop: the released prop nearest its L marker (put there by <see cref="Setup"/>; within 300u, so
	/// one the hunter holds out to the side is still found — stations are 900u apart).</summary>
	static HiderController LooseOf( string scen )
	{
		if ( Marker( scen, "L" ) is not { } l )
			return null;
		foreach ( var id in PropClaims.Current?.Held.Values ?? Enumerable.Empty<Guid>() ) // (one the hunter holds for this station)
			if ( S.Directory.FindByGuid( id )?.Components.Get<HiderController>() is { } held && PropClaims.IsReleased( held ) && held.WorldPosition.WithZ( 0 ).Distance( l.WithZ( 0 ) ) < 400f )
				return held;
		return S.GetAllComponents<HiderController>().Where( h => PropClaims.IsReleased( h ) && h.WorldPosition.Distance( l ) < 300f )
			.OrderBy( h => h.WorldPosition.Distance( l ) ).FirstOrDefault();
	}

	static readonly Dictionary<string, Guid> _loose = new(); // host: station → its loose prop
	static int _parked; // host: strays parked so far (their slots in the park row)

	static void Put( GameObject g, Vector3 p, Rotation r )
	{
		var b = Sim?.Bodies.FirstOrDefault( x => x.Spec.Source == g.Id );
		if ( b is not null && b.Phys.IsValid() )
		{
			b.Phys.Position = p; b.Phys.Rotation = r; b.Phys.Velocity = 0; b.Phys.AngularVelocity = 0; b.Phys.Sleeping = false;
			if ( b.Ctrl.Climbing )
				b.Ctrl = SimCtrl.Initial; // (left stuck to the last climb station: moved, it starts on its feet)
		}
		g.WorldPosition = p; g.WorldRotation = r; g.Transform.ClearInterpolation();
	}

	// ── Host: setup ─────────────────────────────────────────────────────────────────────────────────────────

	/// <summary>Host: put players <paramref name="nameA"/> / <paramref name="nameB"/> and the station's loose prop on their
	/// markers (an actor the scenario doesn't use goes to the park). PART 2 (after the hunter's grab) moves A in for swing.</summary>
	public static async Task<string> Setup( string scen, string nameA, string nameB, int part = 1 )
	{
		if ( Networking.IsActive && !Networking.IsHost )
			return "Setup runs on the HOST";
		if ( Station( scen ) is null )
			return $"no station 'SimLab.{scen}' — is Assets/scenes/Tests/SimLab.scene open?";
		SetStatus( $"SimLab · {scen}\nhost: setting up the station" );
		var a = PropOf( nameA ); var b = PropOf( nameB );
		if ( a is null || b is null )
			return $"players not found: A '{nameA}' {a is not null}, B '{nameB}' {b is not null}";
		var up = Vector3.Up * 2f;
		if ( part == 2 )
		{
			if ( scen == "swing" )
				Put( a.GameObject, Marker( scen, "A" ).Value + up, Rotation.FromYaw( 90f ) );
			return "part 2 done";
		}
		a.LabDown = false;
		b.LabDown = scen == "lying";
		Put( a.GameObject, (Marker( scen, scen == "swing" ? "A.wait" : "A" ) ?? Marker( "park", "A" ).Value) + up, Rotation.FromYaw( 90f ) );
		Put( b.GameObject, (Marker( scen, "B" ) ?? Marker( "park", "B" ).Value) + up, Rotation.FromYaw( -90f ) );
		string loose = "";
		var pcs = PropClaims.Current;
		bool Converted( HiderController h ) => h is not null && PropClaims.IsReleased( h ) && pcs.IsConverted( h.GameObject ); // (scenery made loose, never a released PLAYER prop)
		if ( Marker( scen, "L" ) is { } lm )
		{
			if ( !_loose.TryGetValue( scen, out var id ) || !S.Directory.FindByGuid( id ).IsValid() )
			{
				// Made in an earlier run (a hotload clears _loose): its tag, else the converted prop nearest the marker; else
				// convert the station's football; else (its football converted and flung off before tagging) a stray one.
				var tagged = S.GetAllObjects( true ).FirstOrDefault( g => g.Name == $"SimLab.{scen}.loose" )?.Components.Get<HiderController>();
				var pawn = (Converted( tagged ) ? tagged : null)?.GameObject
					?? S.GetAllComponents<HiderController>().Where( x => Converted( x ) && !x.GameObject.Name.StartsWith( "SimLab." ) && x.WorldPosition.WithZ( 0 ).Distance( lm.WithZ( 0 ) ) < 450f )
						.OrderBy( x => x.WorldPosition.Distance( lm ) ).FirstOrDefault()?.GameObject;
				if ( pawn is null )
				{
					var src = S.GetAllObjects( true ).FirstOrDefault( g => g.Name == $"SimLab.{scen}.L" );
					pawn = pcs.LabMakeLoose( src?.Components.Get<SdfSculpture>( FindMode.EverythingInSelfAndDescendants ) );
					if ( pawn is not null )
						await GameTask.Delay( 500 ); // (registered in the sim as a loose body first)
				}
				pawn ??= S.GetAllComponents<HiderController>().Where( x => Converted( x ) && !x.GameObject.Name.StartsWith( "SimLab." ) )
					.OrderBy( x => x.WorldPosition.Distance( lm ) ).FirstOrDefault()?.GameObject;
				if ( pawn is null )
					return $"could not make the loose prop for {scen}";
				pawn.Name = $"SimLab.{scen}.loose"; // (host-side tag: found again wherever a test left it)
				_loose[scen] = id = pawn.Id;
			}
			Put( S.Directory.FindByGuid( id ), lm + Vector3.Up * 6f, Rotation.Identity );
			loose = $" L {lm:0}";
		}
		// Strays (released props left in this station by earlier tests or by closed clients) go to the park row.
		{
			var centre = Station( scen ).WorldPosition;
			_loose.TryGetValue( scen, out var mine );
			foreach ( var x in S.GetAllComponents<HiderController>().Where( x => PropClaims.IsReleased( x ) && x.GameObject.Id != mine && x.WorldPosition.WithZ( 0 ).Distance( centre.WithZ( 0 ) ) < 500f ).ToList() )
			{
				int slot = _parked++;
				Put( x.GameObject, Marker( "park", "A" ).Value + new Vector3( -300f - 120f * (slot % 12), -400f - 120f * (slot / 12 % 6), 10f ), Rotation.Identity );
			}
		}
		if ( scen == "lying" )
		{
			await GameTask.Delay( 400 ); // the redrive to DOWN lands, then lay it on its side
			Put( b.GameObject, Marker( scen, "B" ).Value + Vector3.Up * 20f, Rotation.From( 0f, 0f, 90f ) );
		}
		await GameTask.Delay( 300 );
		return $"setup {scen}: A {a.WorldPosition:0} B {b.WorldPosition:0}{loose}";
	}

	// ── Hunter client: prepare ──────────────────────────────────────────────────────────────────────────────

	static bool HunterHolds( string scen ) => scen is "held" or "swing" or "throw" or "throwplayer";

	/// <summary>H: let go of anything; then grab what the scenario holds (turning slowly to its start aim), or stand at the
	/// station's watch spot.</summary>
	// The lab's hunter onto a spot: a sim body (mimi_sim_hunter) is the host's to move — Teleport asks it (HunterController.PlaceInSim).
	static void PlaceHunter( HunterController me, Vector3 p )
	{
		if ( me.SimWalking )
			me.Teleport( p, Rotation.Identity );
		else
		{
			me.WorldPosition = p;
			me.GameObject.Transform.ClearInterpolation();
		}
	}

	public static async Task<string> HunterPrepare( string scen, string nameB )
	{
		SetStatus( $"SimLab · {scen}\nH: getting ready" + (HunterHolds( scen ) ? " (grabbing what it holds)" : " (going to the watch spot)") );
		var me = S.GetAllComponents<HunterController>().FirstOrDefault( x => !x.IsProxy );
		var ctl = me?.Components.Get<PlayerController>();
		var pc = PropClaims.Current;
		if ( me is null || ctl is null || pc is null )
			return "no local hunter";
		if ( pc.Held.TryGetValue( Connection.Local.Id, out var held ) && S.Directory.FindByGuid( held ) is { } hg )
			me.LetGo( hg, false );
		HunterController.DebugGrabHold = false;
		await GameTask.Delay( 300 );
		var a = ctl.EyeAngles;
		if ( scen == "hcorner" )
		{
			// The climb test: face the pillar from its H marker (Run grabs it and climbs round).
			PlaceHunter( me, Marker( scen, "H" ).Value + Vector3.Up * 2f );
			a.yaw = 90f; a.pitch = 0f; ctl.EyeAngles = a;
			return $"H at the pillar of {scen}";
		}
		if ( !HunterHolds( scen ) )
		{
			var spot = Marker( scen, "Hobs" ) ?? Marker( "park", "H" ).Value;
			PlaceHunter( me, spot + Vector3.Up * 2f );
			var look = (Station( scen )?.WorldPosition ?? spot) - spot;
			a.yaw = look.EulerAngles.yaw; a.pitch = 10f; ctl.EyeAngles = a;
			return $"H watching {scen} from {spot:0}";
		}
		PlaceHunter( me, Marker( scen, "H" ).Value + Vector3.Up * 2f );
		a.yaw = -90f; a.pitch = 25f; ctl.EyeAngles = a;
		await GameTask.Delay( 400 );
		var target = scen == "throwplayer" ? PropOf( nameB )?.GameObject : LooseOf( scen )?.GameObject;
		if ( target is null )
			return "nothing to grab";
		HunterController.DebugGrabHold = true;
		pc.RequestGrab( target );
		double t0 = Time.NowDouble;
		while ( Time.NowDouble - t0 < 3 && !(pc.Held.TryGetValue( Connection.Local.Id, out held ) && held == target.Id) )
			await GameTask.Delay( 20 );
		if ( held != target.Id )
			return $"grab failed (held {held})";
		float yaw0 = scen switch { "swing" => -30f, "throw" or "throwplayer" => 30f, _ => -90f };
		double t1 = Time.NowDouble;
		while ( Time.NowDouble - t1 < 1.0 )
		{
			await GameTask.Delay( 1 );
			a.yaw = (float)(-90.0 + (yaw0 + 90.0) * Math.Min( 1.0, (Time.NowDouble - t1) / 1.0 ));
			ctl.EyeAngles = a;
		}
		await GameTask.Delay( 300 );
		return $"H holding '{target.Name}' at yaw {ctl.EyeAngles.yaw:0}";
	}

	// ── Every screen: act + record ──────────────────────────────────────────────────────────────────────────

	// Walk windows: (from s, to s, marker). The actor walks at its marker while the window is open.
	static (double, double, string)[] Walks( string scen, string role ) => (role, scen) switch
	{
		("A", "loose" or "push" or "jump") => new[] { (0.5, 2.3, "A.to") },
		("A", "held") => new[] { (0.5, 2.6, "A.to") },
		("A", "lying") => new[] { (1.0, 3.0, "A.to") },
		("A", "static") => new[] { (0.5, 2.5, "A.to"), (2.5, 3.5, "A.to2") },
		("A", "headon") => new[] { (0.5, 2.0, "A.to") },
		("A", "wall") => new[] { (0.5, 3.0, "A.to") },
		("A", "ledge") => new[] { (0.5, 2.0, "Ledge") }, // (to the ledge's centre and stop there: it jumps on at 165u and lands on top)
		("A", "pushwall") => new[] { (0.5, 3.2, "A.to") },
		("A", "twopush") => new[] { (0.5, 2.5, "A.to") },
		("A", "climb" or "corner" or "inner") => new[] { (0.5, 10.0, "A.to") }, // (to the wall; Act jumps at it and climbs)
		("B", "headon") => new[] { (0.5, 2.0, "B.to") },
		("B", "twopush") => new[] { (0.5, 2.5, "B.to") },
		_ => Array.Empty<(double, double, string)>(),
	};

	// The pair whose contact matters: two of A / B / L, or A and a static thing (Cone, Wall, Ledge).
	static (string, string) PairOf( string scen ) => scen switch
	{
		"loose" or "held" or "swing" or "pushwall" or "twopush" => ("A", "L"),
		"throw" => ("L", "A"),
		"throwplayer" => ("B", "A"),
		"static" => ("A", "Cone"),
		"wall" => ("A", "Wall"),
		"ledge" => ("A", "Ledge"),
		"climb" => ("A", "Wall"),
		"corner" => ("A", "Pillar"),
		"inner" => ("A", "WallA"),
		_ => ("A", "B"),
	};

	struct Sample
	{
		public double T; public int Tick;
		public bool[] Ok; public Vector3[] P; public BBox[] Box; public Vector3[] CopyP; public BBox[] CopyBox; public Vector3[] CopyV;
		public bool[] Auth; public Vector3[] Off; public bool[] Touched; public bool[] Tracking; public int[] Drv;
		public bool AClimb; public Vector3 AN; public bool HClimb; public Vector3 HN; public Vector3 HP; // (climbing: A's sim climb on this machine; H's own climb, on H)
	}

	/// <summary>Every screen (role A, B, H or HOST): act the role's part of <paramref name="scen"/> for <paramref name="seconds"/>
	/// and return one summary line (plus a frame dump around the pair's deepest moment when <paramref name="dump"/>).</summary>
	public static async Task<string> Run( string scen, string role, string nameA, string nameB, float seconds = 6f, bool dump = false )
	{
		var sim = Sim;
		if ( sim is null || Station( scen ) is null )
			return $"{role,-4} no sim / no station '{scen}'";
		SimLabJumpWatch.SetPhase( $"run {scen}" );
		if ( ClimbScen( scen ) )
			seconds = role == "HOST" ? 13f : 10f; // (the host starts first and records longer — see lab.sh)
		var hA = PropOf( nameA ); var hB = PropOf( nameB ); var hL = LooseOf( scen );
		var names = new[] { "A", "B", "L" };
		var keys = new[] { hA?.GameObject.Id ?? Guid.Empty, hB?.GameObject.Id ?? Guid.Empty, hL?.GameObject.Id ?? Guid.Empty };
		var (pairA, pairB) = PairOf( scen );
		int ia = Array.IndexOf( names, pairA ), ib = Array.IndexOf( names, pairB ); // ib -1 = a static thing
		var stat = ib < 0 ? StaticOf( scen, pairB ) : null;
		BBox statBox = stat?.GetBounds() ?? default;
		var meProp = role is "A" ? hA : role is "B" ? hB : null;
		var me = role == "H" ? S.GetAllComponents<HunterController>().FirstOrDefault( x => !x.IsProxy ) : null;
		var ctl = me?.Components.Get<PlayerController>();
		bool jumped = false, thrown = false, hGrabbed = false;
		double climbT = -1;
		var hClimb = me?.Components.Get<HunterClimb>();
		var walks = Walks( scen, role );

		// A's climb: jump at the wall (Space held from the jump — the grab's intent), then by scenario: up and over the top
		// (climb), or up 0.8 s and then sideways — D, looking at the wall — for the rest (corner, inner).
		void ActClimb( double t )
		{
			var wall = StaticOf( scen, scen == "climb" ? "Wall" : scen == "inner" ? "WallA" : "Pillar" );
			if ( wall is null || hA is null )
				return;
			float face = wall.GetBounds().Mins.y;
			bool climbing = hA.SimClimbing;
			if ( climbing && climbT < 0 )
				climbT = t;
			if ( !jumped && t > 0.5 && face - hA.WorldPosition.y < 90f )
			{
				hA.LabJump();
				jumped = true;
				HiderController.DebugClimbVertical = 1f;
			}
			if ( climbT < 0 )
				return;
			if ( scen == "climb" )
			{
				if ( !climbing )
					HiderController.DebugClimbVertical = 0f; // mantled: walk on over the top to A.to
				return;
			}
			HiderController.DebugGoto = null;
			if ( t - climbT > 0.8 )
			{
				HiderController.DebugClimbVertical = 0f;
				HiderController.DebugClimbYaw = 90f;
				HiderController.DebugClimbMove = new Vector2( 0f, -1f );
			}
		}

		void Act( double t )
		{
			if ( meProp is not null )
			{
				Vector3? to = null;
				foreach ( var (from, until, m) in walks )
					if ( t >= from && t < until )
						to = Marker( scen, m );
				HiderController.DebugGoto = to;
				if ( role == "A" && !jumped && scen == "jump" && hB is not null && hA.WorldPosition.WithZ( 0 ).Distance( hB.WorldPosition.WithZ( 0 ) ) < 110f )
				{ hA.LabJump(); jumped = true; }
				if ( role == "A" && !jumped && scen == "ledge" && Marker( scen, "Ledge" ) is { } lg && hA.WorldPosition.WithZ( 0 ).Distance( lg.WithZ( 0 ) ) < 165f )
				{ hA.LabJump(); jumped = true; }
				if ( role == "A" && ClimbScen( scen ) )
					ActClimb( t );
			}
			if ( role == "H" && scen == "hcorner" && hClimb is not null )
			{
				// Grab the pillar, climb up a second, then sideways (D) for the rest — round its corners.
				if ( !hGrabbed && t > 0.3 ) { hGrabbed = true; if ( me.SimWalking ) me.LabSimGrab(); else hClimb.LabGrab(); HunterClimb.DebugVertical = 1f; }
				if ( hGrabbed && t > 1.3 ) { HunterClimb.DebugVertical = 0f; HunterClimb.DebugMove = new Vector3( 0f, -1f, 0f ); }
			}
			if ( role != "H" || ctl is null || !HunterHolds( scen ) )
				return;
			var a = ctl.EyeAngles;
			if ( scen == "held" ) { a.yaw = -90f; a.pitch = 25f; }
			else if ( scen == "swing" ) { a.yaw = t < 1.5 ? -30f : t < 2.1 ? (float)(-30.0 - 120.0 * (t - 1.5) / 0.6) : -150f; a.pitch = 25f; }
			else
			{
				a.yaw = t < 1.0 ? 30f : t < 1.25 ? (float)(30.0 - 60.0 * (t - 1.0) / 0.25) : -30f; a.pitch = 15f;
				if ( t >= 1.25 && !thrown )
				{
					thrown = true;
					var go = S.Directory.FindByGuid( scen == "throwplayer" ? keys[1] : keys[2] );
					if ( go.IsValid() ) me.LetGo( go, false );
					HunterController.DebugGrabHold = false;
				}
			}
			ctl.EyeAngles = a;
		}

		var fr = new List<Sample>();
		double t0 = Time.NowDouble;
		while ( Time.NowDouble - t0 < seconds )
		{
			await GameTask.Delay( 1 );
			double t = Time.NowDouble - t0;
			Act( t );
			SetStatus( $"SimLab · {scen}\n{RoleName( role )}: {Doing( t )}\n{t:0.0} / {seconds:0} s" );
			var s = new Sample
			{
				T = t, Tick = sim.Tick, Ok = new bool[3], P = new Vector3[3], Box = new BBox[3], CopyP = new Vector3[3], CopyBox = new BBox[3], CopyV = new Vector3[3],
				Auth = new bool[3], Off = new Vector3[3], Touched = new bool[3], Tracking = new bool[3], Drv = new int[3],
			};
			for ( int i = 0; i < 3; i++ )
			{
				var b = keys[i] == Guid.Empty ? null : sim.Bodies.FirstOrDefault( x => x.Key == keys[i] );
				if ( b is null || !b.Phys.IsValid() || !sim.TryGetVisualPose( keys[i], out var vp ) )
					continue;
				s.Ok[i] = true; s.P[i] = vp.Position; s.CopyP[i] = b.Phys.Position; s.CopyV[i] = b.Phys.Velocity;
				s.CopyBox[i] = b.Phys.GetBounds(); s.Box[i] = s.CopyBox[i].Translate( vp.Position - b.Phys.Position );
				s.Auth[i] = b.ShownFromAuth; s.Off[i] = b.PosOffset; s.Tracking[i] = b.Tracking; s.Drv[i] = b.Spec.Driver;
				s.Touched[i] = b.LocalTouched || sim.Tick - b.TouchedTick <= 24;
			}
			if ( keys[0] != Guid.Empty && sim.Find( keys[0] ) is { } ab )
			{
				s.AClimb = ab.Ctrl.Climbing; s.AN = ab.Ctrl.ClimbN;
			}
			if ( hClimb is not null )
			{
				s.HClimb = me.Clinging; s.HN = me.SimWalking ? me.SimClimbNormal : hClimb.LabNormal; s.HP = me.WorldPosition;
			}
			fr.Add( s );
		}
		if ( meProp is not null )
			HiderController.DebugGoto = null;
		if ( ClimbScen( scen ) )
		{
			HiderController.DebugClimbVertical = 0f; HiderController.DebugClimbMove = Vector2.Zero; HiderController.DebugClimbYaw = null;
			HunterClimb.DebugVertical = 0f; HunterClimb.DebugMove = null;
		}
		SetStatus( $"SimLab · {scen} done\n{RoleName( role )}: waiting for the next scenario" );
		SimLabJumpWatch.SetPhase( $"idle after {scen}" );
		// The jump watch's count since the last run joins this line; its detail lines go last (see SimLabJumpWatch).
		var result = Analyse( role, scen, fr, names, ia, ib, pairB, statBox, dump );
		var jumps = SimLabJumpWatch.TakeReport();
		int cut = jumps.IndexOf( '\n' );
		string head = cut < 0 ? jumps : jumps[..cut], details = cut < 0 ? "" : jumps[cut..];
		int nl = result.IndexOf( '\n' );
		return (nl < 0 ? result + head : result[..nl] + head + result[nl..]) + details;

		// What this machine is doing right now, for the on-screen status.
		string Doing( double t )
		{
			if ( role == "HOST" ) return "recording the truth";
			if ( role == "H" && scen == "hcorner" )
				return !hGrabbed ? "facing the pillar" : t < 1.3 ? "grabbed - climbing up" : me?.Clinging == true ? "climbing sideways (D) round the pillar" : "fell off";
			if ( role == "A" && ClimbScen( scen ) && climbT >= 0 )
				return !hA.SimClimbing ? (scen == "climb" ? "mantled - walking onto the top" : "not climbing (fell off?)") : scen == "climb" ? "climbing up (Space)" : t - climbT < 0.8 ? "climbing up" : "climbing sideways (D)";
			if ( role == "H" )
				return !HunterHolds( scen ) ? "watching" : scen == "held" ? "holding still" : scen == "swing" ? (t < 1.5 ? "holding" : t < 2.1 ? "swinging" : "held out after the swing")
					: thrown ? "thrown - watching it land" : t < 1.0 ? "holding, about to throw" : "throwing";
			foreach ( var (from, until, m) in walks )
				if ( t >= from && t < until )
					return jumped ? $"jumped, walking to {m}" : $"walking to {m}";
			return jumped ? "jumped" : t < 1 ? "standing (about to move)" : "standing";
		}
	}

	static string RoleName( string role ) => role switch { "A" => "A (player prop)", "B" => "B (player prop)", "H" => "H (hunter)", _ => "host" };

	// Penetration depth of two boxes (the smallest overlap over the axes; negative = the gap when apart).
	static float Depth( BBox a, BBox b )
	{
		float ox = MathF.Min( a.Maxs.x, b.Maxs.x ) - MathF.Max( a.Mins.x, b.Mins.x );
		float oy = MathF.Min( a.Maxs.y, b.Maxs.y ) - MathF.Max( a.Mins.y, b.Mins.y );
		float oz = MathF.Min( a.Maxs.z, b.Maxs.z ) - MathF.Max( a.Mins.z, b.Mins.z );
		return MathF.Min( ox, MathF.Min( oy, oz ) );
	}

	static string Analyse( string role, string scen, List<Sample> fr, string[] names, int ia, int ib, string pairB, BBox statBox, bool dump )
	{
		var sb = new StringBuilder();
		sb.Append( $"{role,-4}" );
		for ( int i = 0; i < 3; i++ )
		{
			var dvs = new List<float>(); float maxDv = 0, maxOff = 0; double tMax = 0; int sw = 0;
			for ( int k = 2; k < fr.Count; k++ )
			{
				if ( !fr[k].Ok[i] || !fr[k - 1].Ok[i] || !fr[k - 2].Ok[i] ) continue;
				double d1 = fr[k].T - fr[k - 1].T, d0 = fr[k - 1].T - fr[k - 2].T;
				if ( d1 <= 0 || d0 <= 0 ) continue;
				float dv = ((fr[k].P[i] - fr[k - 1].P[i]) / (float)d1 - (fr[k - 1].P[i] - fr[k - 2].P[i]) / (float)d0).Length;
				dvs.Add( dv );
				if ( dv > maxDv ) { maxDv = dv; tMax = fr[k].T; }
				maxOff = MathF.Max( maxOff, fr[k].Off[i].Length );
				if ( fr[k].Auth[i] != fr[k - 1].Auth[i] ) sw++;
			}
			if ( dvs.Count == 0 ) { sb.Append( $" | {names[i]} -" ); continue; }
			dvs.Sort();
			var okF = fr.Where( f => f.Ok[i] ).ToList();
			float moved = okF[^1].P[i].WithZ( 0 ).Distance( okF[0].P[i].WithZ( 0 ) );
			sb.Append( $" | {names[i]} mv {moved,3:0} max {maxDv,5:0}@{tMax:0.0} p99 {dvs[(int)(dvs.Count * 0.99)],4:0} >1500:{dvs.Count( v => v > 1500f )} off {maxOff,3:0} sw {sw}" );
		}

		// the pair: closest drawn centre distance, deepest drawn box overlap, lowest vertical gap while stacked
		float minC = float.MaxValue, maxD = float.MinValue, minV = float.MaxValue; int kDeep = -1;
		for ( int k = 0; k < fr.Count; k++ )
		{
			var f = fr[k];
			if ( !f.Ok[ia] || (ib >= 0 && !f.Ok[ib]) ) continue;
			var pb = ib >= 0 ? f.P[ib] : statBox.Center; var bb = ib >= 0 ? f.Box[ib] : statBox;
			minC = MathF.Min( minC, f.P[ia].WithZ( 0 ).Distance( pb.WithZ( 0 ) ) );
			float d = Depth( f.Box[ia], bb );
			if ( d > maxD ) { maxD = d; kDeep = k; }
			bool overXY = MathF.Min( f.Box[ia].Maxs.x, bb.Maxs.x ) > MathF.Max( f.Box[ia].Mins.x, bb.Mins.x ) && MathF.Min( f.Box[ia].Maxs.y, bb.Maxs.y ) > MathF.Max( f.Box[ia].Mins.y, bb.Mins.y );
			if ( overXY && f.Box[ia].Center.z > bb.Center.z ) minV = MathF.Min( minV, f.Box[ia].Mins.z - bb.Maxs.z );
		}
		sb.Append( $" | pair {names[ia]}-{(ib >= 0 ? names[ib] : pairB)} centre {minC:0.0} depth {maxD:0.0} vgap {(minV == float.MaxValue ? 999f : minV):0.0}" );

		// throws: the hit timeline on this machine (s after the release seen here; ticks in brackets)
		if ( scen is "throw" or "throwplayer" )
		{
			int ip = ia, it = ib; // projectile, target
			int kRel = -1, kCopy = -1, kReact = -1, kArrive = -1;
			for ( int k = 1; k < fr.Count; k++ )
			{
				var f = fr[k]; var g = fr[k - 1];
				if ( !f.Ok[ip] || !f.Ok[it] || !g.Ok[it] ) continue;
				if ( kRel < 0 && g.Drv[ip] == SimHoldDriver.Id && f.Drv[ip] != SimHoldDriver.Id ) kRel = k;
				if ( kRel < 0 ) continue;
				if ( kCopy < 0 && f.CopyV[it].Length > 60f ) kCopy = k;
				double dt = f.T - g.T;
				if ( kReact < 0 && dt > 0 && (f.P[it] - g.P[it]).Length / dt > 60f ) kReact = k;
				if ( kArrive < 0 && Depth( f.Box[ip], f.Box[it] ) > 0f ) kArrive = k;
			}
			string Ms( int k ) => k < 0 || kRel < 0 ? "-" : $"{(fr[k].T - fr[kRel].T) * 1000:0}ms[{fr[k].Tick - fr[kRel].Tick}t]";
			float gapAtReact = kReact >= 0 ? Depth( fr[kReact].Box[ip], fr[kReact].Box[it] ) : 0f;
			string lead = kReact >= 0 && kArrive >= 0 ? $"{(fr[kReact].T - fr[kArrive].T) * 1000:0}" : "-";
			sb.Append( $" | hit: release@tick {(kRel >= 0 ? fr[kRel].Tick : -1)} copyhit {Ms( kCopy )} react {Ms( kReact )} arrive {Ms( kArrive )} react-arrive {lead}ms gap@react {gapAtReact:0}u" );
		}

		if ( ClimbScen( scen ) )
			sb.Append( ClimbReport( fr, scen == "hcorner", Station( scen )?.WorldPosition ?? Vector3.Zero ) );

		if ( dump && kDeep >= 0 )
		{
			sb.AppendLine();
			for ( int k = Math.Max( 0, kDeep - 30 ); k < Math.Min( fr.Count, kDeep + 30 ); k += 3 )
			{
				var f = fr[k];
				var bb = ib >= 0 ? f.Box[ib] : statBox; var cb = ib >= 0 ? f.CopyBox[ib] : statBox;
				string Who( int i ) => i < 0 ? pairB : $"{names[i]} src {(f.Auth[i] ? "host" : "copy")} off {f.Off[i].Length,4:0} touched {f.Touched[i]} trk {f.Tracking[i]} drv {f.Drv[i]}";
				sb.AppendLine( $"   {f.T:0.00}s drawn depth {Depth( f.Box[ia], bb ),6:0.0} copy depth {Depth( f.CopyBox[ia], cb ),6:0.0} | {Who( ia )} | {Who( ib )}" );
			}
		}
		return sb.ToString();
	}

	// The climb on this machine: the share of frames climbing, the faces climbed in order (a new face = a normal more than
	// ~45° from the last), the highest and final drawn position (station-local). A: its sim body (own prediction, a copy,
	// or the host's); H: its own climb, on its own machine only.
	static string ClimbReport( List<Sample> fr, bool hunter, Vector3 origin )
	{
		int n = 0, climbing = 0; var faces = new List<Vector3>(); float maxZ = float.MinValue; Vector3 last = default;
		foreach ( var f in fr )
		{
			if ( hunter ? f.HP == Vector3.Zero : !f.Ok[0] )
				continue;
			var p = hunter ? f.HP : f.P[0];
			n++; last = p; maxZ = MathF.Max( maxZ, p.z );
			bool c = hunter ? f.HClimb : f.AClimb;
			var nn = hunter ? f.HN : f.AN;
			if ( !c || nn.IsNearZeroLength )
				continue;
			climbing++;
			if ( faces.Count == 0 || Vector3.Dot( faces[^1], nn ) < 0.7f )
				faces.Add( nn );
		}
		if ( n == 0 )
			return $" | climb {(hunter ? "H" : "A")} -";
		static string Dir( Vector3 v ) => MathF.Abs( v.z ) > 0.7f ? (v.z > 0 ? "up" : "down") : MathF.Abs( v.x ) > MathF.Abs( v.y ) ? (v.x > 0 ? "+x" : "-x") : (v.y > 0 ? "+y" : "-y");
		var e = last - origin;
		return $" | climb {(hunter ? "H" : "A")} {100 * climbing / n}% faces {faces.Count} [{string.Join( ",", faces.Select( Dir ) )}] maxz {maxZ - origin.z:0} end {e.x:0},{e.y:0},{e.z:0}";
	}

	// ── On-screen status (every lab machine: SimLabOverlay draws it) ──
	static string _status = "";
	static RealTimeSince _statusAge = 999f;
	/// <summary>What this machine is doing in the lab right now; empty once nothing has happened for 30 s.</summary>
	public static string StatusText => _statusAge < 30f ? _status : "";
	static void SetStatus( string s ) { _status = s; _statusAge = 0f; }

	/// <summary>The fake lag lab.sh last set on this client (ms), for the on-screen conditions; null = not set by the lab.
	/// Compare it with the measured round trip next to it: in one editor session net_fakelag silently stopped applying.</summary>
	/// <summary>lab.sh, on every machine: what the lab is doing now (the jump watch counts "setup …" teleports apart).</summary>
	public static string NotePhase( string phase ) { SimLabJumpWatch.SetPhase( phase ); return $"phase {phase}"; }

	public static string FakeLagNote { get; private set; }
	public static string NoteFakeLag( string ms ) { FakeLagNote = ms; return $"noted fake lag {ms} ms"; }

	// ── Observer client ──
	/// <summary>An OBSERVER client (lab.sh watch): fly this machine's free cam (the creative ghost) to look over the station
	/// of <paramref name="scen"/> — lab.sh calls it as each scenario starts. Not one of the actors; nothing is recorded.</summary>
	public static async Task<string> Observe( string scen )
	{
		var me = S.GetAllComponents<HunterController>().FirstOrDefault( x => !x.IsProxy );
		var st = Station( scen );
		if ( me is null || st is null )
			return $"observer: {(me is null ? "no local hunter" : $"no station {scen}")}";
		if ( !me.FreeCamming )
		{
			me.LabSetFreeCam( true );
			await GameTask.Delay( 250 ); // (it takes off from the live camera on its first frame; place it after that)
		}
		var target = st.WorldPosition + Vector3.Up * 30f;
		var eye = st.WorldPosition + new Vector3( -420f, -420f, 300f );
		SpectatorController.Local?.LabPlace( eye, Rotation.LookAt( target - eye ).Angles() );
		SetStatus( $"SimLab · {scen}\nobserver: watching (free cam - fly with WASD, B to stop)" );
		return $"observer looking at {scen}";
	}

	[ConCmd( "mimi_lab_scenarios", Help = "List the SimLab collision scenarios (run them with Tools/SimLab/lab.sh)." )]
	public static void ListCmd() => Log.Info( "SimLab scenarios: " + string.Join( " ", Scenarios ) );
}

/// <summary>Draws <see cref="SimLab.StatusText"/> on screen on every machine taking part in a SimLab run.</summary>
public sealed class SimLabOverlay : GameObjectSystem
{
	public SimLabOverlay( Scene scene ) : base( scene )
	{
		Listen( Stage.FinishUpdate, 0, Draw, "SimLabOverlay" );
	}

	void Draw()
	{
		var text = SimLab.StatusText;
		if ( string.IsNullOrEmpty( text ) )
			return;
		Scene.DebugOverlay.ScreenText( new Vector2( 20, 160 ), text, size: 20, flags: TextFlag.LeftTop, color: Color.Yellow );
		int lines = text.Split( (char)10 ).Length;
		Scene.DebugOverlay.ScreenText( new Vector2( 20, 166 + 24 * lines ), Conditions(), size: 16, flags: TextFlag.LeftTop, color: Color.Cyan );
	}

	// The test conditions on this machine: the fake lag it adds, and what the sim measures (round trip, how far it
	// predicts ahead, how far behind other players' bodies are drawn). net_fakelag adds that many ms each way, roughly
	// round trip = 2 x lag + ~20 ms on loopback (memory: fakelag-calibration).
	string Conditions()
	{
		var sim = Scene.GetSystem<SimWorld>();
		if ( !Networking.IsActive || Networking.IsHost )
			return $"host · sim {SimWorld.TickRate} Hz · {Connection.All.Count - 1} client(s)";
		string lag = SimLab.FakeLagNote ?? "?"; // (set by lab.sh lag: game code can't read the engine's net_fakelag - it comes back unset)
		if ( sim is null || !sim.Active )
			return $"fake lag set {lag} ms";
		string rtt = sim.RoundTripMs < 0f ? "measuring" : $"{sim.RoundTripMs:0} ms";
		return $"fake lag set {lag} ms · measured round trip {rtt} · predicting {sim.LeadMs:0} ms ahead · others drawn {sim.DisplayGapMs:0} ms behind";
	}
}
